package com.bank.portfolio.service;

import java.util.logging.Logger;

// Maximizes expected return within a budget, each product chosen at most once.
public class PortfolioKnapsackService {
    private static final Logger log = Logger.getLogger(PortfolioKnapsackService.class.getName());

    public int maxReturn(int[] costs, int[] returns, int budget) {
        // One-dimensional DP over capacity; dp[c] = best return with budget c.
        int[] dp = new int[budget + 1];
        for (int i = 0; i < costs.length; i++) {
            // Iterate capacity high to low so each product is used at most once.
            for (int c = budget; c >= costs[i]; c--) {
                dp[c] = Math.max(dp[c], returns[i] + dp[c - costs[i]]);
            }
        }
        log.info(() -> "Max return within budget = " + dp[budget]);
        return dp[budget];
    }
}
