package com.bank.portfolio;

import com.bank.portfolio.service.PortfolioKnapsackService;
import java.util.logging.Logger;

public class PortfolioKnapsackApplication {
    private static final Logger log = Logger.getLogger(PortfolioKnapsackApplication.class.getName());

    public static void main(String[] args) {
        PortfolioKnapsackService service = new PortfolioKnapsackService();
        int[] costs = {2, 3, 4, 5};       // product costs (in lakhs)
        int[] returns = {3, 4, 5, 6};     // expected returns (in lakhs)
        int budget = 5;                   // Rajesh's budget (in lakhs)
        int best = service.maxReturn(costs, returns, budget);
        log.info("Best expected return within budget " + budget + " lakh: " + best + " lakh");
    }
}
